mapper.select:
SELECT 
  FROM biz90_limit
 WHERE biz90_company_id = #{companyId}
   AND biz90_limit_id = #{limitId}

mapper.update:
UPDATE biz90_limit
   SET biz90_start_date       = #{req.startDate},
       biz90_provide_rcv_type = #{req.provideRcvType},
       biz90_sale_rule_limit1 = #{req.saleRuleLimit1},
       biz90_sale_rule_limit2 = #{req.saleRuleLimit2},
       biz90_company_limit1   = #{req.companyLimit1},
       biz90_company_limit2   = #{req.companyLimit2},
       biz90_company_limit3   = #{req.companyLimit3}
 WHERE biz90_limit_id   = #{req.limitId}
   AND biz90_company_id = #{companyId}

mapper.delete:
DELETE FROM biz90_limit
 WHERE biz90_limit_id   = #{limitId}
   AND biz90_company_id = #{companyId}
